package dev.zomboid.gore;
import java.util.*;
/** Arterial pulses follow living pressure; corpses only have short residual drainage. */
public final class Artery14 {
 static final Map<Object,State> LIVE=new WeakHashMap<>(),DEAD=new WeakHashMap<>();static Object level;static long budgetTick=-1;static int particles,sounds;static Object spraySound,impactSound;static boolean reported;static final Deque<Long> SOUND_STARTS=new ArrayDeque<>();static final Map<Object,Deque<Long>> SERVER_SOUNDS=new WeakHashMap<>();static final Map<Object,Long> SERVER_AFTER=new WeakHashMap<>();
 static final class State{int serial,region;long start=-1000,last=-1,soundAt=-1000,deadUntil;}
 static void frame(Object w,long now){if(level!=w){level=w;LIVE.clear();DEAD.clear();SOUND_STARTS.clear();budgetTick=-1;}if(now!=budgetTick){budgetTick=now;particles=0;sounds=0;while(!SOUND_STARTS.isEmpty()&&now-SOUND_STARTS.peekFirst()>=20)SOUND_STARTS.removeFirst();}}
 static boolean arterial(int region,double relative,int hits){return region==0&&relative>=.73&&relative<=.88||region>=2&&region<=5&&hits>=2||region>=6&&hits>=3;}
 public static void injure(Object n,Gore.Shot shot,float damage,int ignored){if(damage<=0)return;int region=Ballistics11.zone(shot);if(region==1)region=0;Object tag=Gore.tag(n);int hits=((Number)R.call(tag,"getInt","zg13_hits_"+region)).intValue();double relative=(R.num(R.get(shot.point(),"y"))-R.num(R.call(n,"getY")))/Math.max(.1,R.num(R.call(n,"getBbHeight")));if(!arterial(region,relative,hits))return;Object world=R.call(n,"level");long now=((Number)R.call(world,"getGameTime")).longValue();serverSound(world,n,R.num(R.get(shot.point(),"x")),R.num(R.get(shot.point(),"y")),R.num(R.get(shot.point(),"z")),now);int serial=((Number)R.call(tag,"getInt","zg13_serial")).intValue();R.call(R.call(n,"getEntityData"),"set",Trauma13.impactAccessor,(serial<<4)|region|8);}
 static void serverSound(Object world,Object entity,double x,double y,double z,long now){try{Deque<Long>q=SERVER_SOUNDS.computeIfAbsent(world,k->new ArrayDeque<>());while(!q.isEmpty()&&now-q.peekFirst()>=20)q.removeFirst();if(q.size()>=4||now<SERVER_AFTER.getOrDefault(entity,-1000L))return;if(spraySound==null)spraySound=makeSound("artery_pulse14");R.call(world,"playSound",null,x,y,z,spraySound,R.get(R.type("net.minecraft.sounds.SoundSource"),"HOSTILE"),.42f,.95f);q.addLast(now);SERVER_AFTER.put(entity,now+30);}catch(RuntimeException e){if(!reported){reported=true;System.err.println("[Gore14] Artery sound: "+e);}}}
 static void sound(Object w,double x,double y,double z,State s,long now,boolean arterial){if(sounds>=2||SOUND_STARTS.size()>=4||now-s.soundAt<30)return;Object snd;if(arterial){if(spraySound==null)spraySound=makeSound("artery_pulse14");snd=spraySound;}else{if(impactSound==null)impactSound=makeSound("wet_impact14");snd=impactSound;}s.soundAt=now;sounds++;SOUND_STARTS.addLast(now);R.call(w,"playLocalSound",x,y,z,snd,R.get(R.type("net.minecraft.sounds.SoundSource"),"HOSTILE"),arterial?.42f:.25f,.95f,false);}
 static Object makeSound(String key){return R.call(R.type("net.minecraft.sounds.SoundEvent"),"createVariableRangeEvent",R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","zomboid_gore",key));}
 static void pulse(Object w,double x,double y,double z,double dx,double dz,long age){if(Blood12.particle==null)Blood12.emit(w,x,y,z,false,0);if(Blood12.particle==null)return;double pulse=Math.pow(Math.max(0,Math.sin((age%14)*Math.PI/7)),2);if(pulse<.25)return;double speed=(.12+.16*pulse)*Math.max(.15,1-age/100d);for(int i=0;i<2&&particles<12&&Blood12.used<48;i++){particles++;Blood12.used++;R.call(w,"addParticle",Blood12.particle,x,y,z,dx*speed,.045+pulse*.045,dz*speed);}}
 public static void tick(Object event){try{Object n=R.call(event,"getEntity");if(!Gore.zombie(n))return;Object w=R.call(n,"level");if(!R.yes(R.get(w,"isClientSide")))return;long now=((Number)R.call(w,"getGameTime")).longValue();frame(w,now);int value=((Number)R.call(R.call(n,"getEntityData"),"get",Trauma13.impactAccessor)).intValue();State s=LIVE.computeIfAbsent(n,k->new State());if(value!=s.serial){s.serial=value;if((value&8)!=0){s.start=now;s.region=value&7;s.soundAt=now-30;}}
 if(s.last==now)return;s.last=now;long age=now-s.start;if(age<0||age>80||!R.yes(R.call(n,"isAlive")))return;Object player=R.get(R.call(R.type("net.minecraft.client.Minecraft"),"getInstance"),"player");if(player==null||R.num(R.call(n,"distanceToSqr",player))>24*24)return;double yaw=Math.toRadians(R.num(R.call(n,"getYRot"))),x=R.num(R.call(n,"getX")),y=R.num(R.call(n,"getY")),z=R.num(R.call(n,"getZ")),h=R.num(R.call(n,"getBbHeight"));double side=s.region==2?.23:s.region==3?-.23:s.region==4?.12:s.region==5?-.12:0;double height=s.region==0?.77:s.region<4?.65:s.region<6?.27:.56;x+=Math.cos(yaw)*side;y+=h*height;z+=Math.sin(yaw)*side;sound(w,x,y,z,s,now,true);pulse(w,x,y,z,-Math.sin(yaw),Math.cos(yaw),age);
 }catch(RuntimeException e){if(!reported){reported=true;System.err.println("[Gore14] Artery tick: "+e);}}}
 public static void deadEmit(Object w,double x,double y,double z,boolean head,int count){Blood12.emit(w,x,y,z,false,Math.min(1,count));}
 public static void ragdoll(Object rag){try{Object snap=R.call(rag,"getSnapshot");if(snap==null)return;Object w=R.get(R.call(R.type("net.minecraft.client.Minecraft"),"getInstance"),"level");if(w==null)return;long now=((Number)R.call(w,"getGameTime")).longValue();frame(w,now);State s=DEAD.computeIfAbsent(rag,k->new State());if(s.last==now)return;s.last=now;long until=((Number)R.get(rag,"goreBleedUntil13")).longValue();if(until<=now||until==s.deadUntil)return;s.deadUntil=until;Object p=R.call(rag,"getSmoothedTorsoPos");sound(w,R.num(R.get(p,"x")),R.num(R.get(p,"y")),R.num(R.get(p,"z")),s,now,false);
 }catch(RuntimeException e){/* Optional external ragdoll can lack trauma fields. */}}
}
